/**
 * src/ez-trees.js: OUR TREES, GENERATED BY EZ-TREE IN THE APPLICATION (#480g, asked by Durzo on 15 Nov. 2026).
 *
 * A tree is a species (src/tree-species.js), a seed (its variant) and a height: the species' EZ-Tree preset with
 * its changes, our foliage drawn on a canvas, its bark. One generation per species and seed, kept: every tree of
 * that variant is a clone of it (shared geometry and materials), set to its height.
 *
 * THREE is the application's global (r128), as for src/vendor/ez-tree/ez-tree.js.
 *
 * The bark and the foliage are read AS THEY ARE (LinearEncoding, three's default): the application's renderer does
 * not re-encode its output in sRGB (model-cache.js, its colours « telles qu'elles s'affichent »). Marked sRGB, they
 * were decoded and never re-encoded: seen, dark green crowns and black trunks.
 */
import { Tree, TreeOptions } from './vendor/ez-tree/ez-tree.js';
import { TREE_PRESETS } from './vendor/ez-tree/presets.js';
import { SPECIES, domCanvas, barkFile } from './tree-species.js';
import { opaqueCutout } from './opaque-cutout.js';

/** Where the application's barks are, from src/index.html. */
const BARK_DIR = '../assets/textures/';

let onBarkLoaded = () => {};

/** What to call when a bark has arrived (a redraw: the trees stood barkless until then). */
export function setSpeciesTreeCallbacks({ onChange }) {
  onBarkLoaded = onChange || (() => {});
}

/**
 * The application's bark of a species: its shipped file, loaded once. Read with an <img> as the bubbles' grains
 * are (bubble-grain.js), not TextureLoader: its `crossOrigin` and a file:// page do not mix, and its error
 * callback is the fourth argument (passed third, a missing bark went unsaid: seen, plain trunks). The texture
 * is given at once and gets its image when it arrives (a redraw then); a bark that cannot be read leaves its
 * trees the plain colour, and says so once. Null where there is no DOM (tests).
 */
const barks = new Map();
const barkMaterials = new Map();
/** The species whose bark has arrived, or will never (missing file): their trees are drawn as they will stay. */
const barksSettled = new Set();
function shippedBark(name) {
  if (typeof document === 'undefined' || typeof Image === 'undefined') return null;
  // A bark drawn (tree-species.js, `barkDrawn`): no file, there at once.
  if (!barks.has(name) && SPECIES[name].barkDrawn) {
    barks.set(name, new THREE.CanvasTexture(SPECIES[name].barkDrawn(1, domCanvas)));
    barksSettled.add(name);
  }
  if (!barks.has(name)) {
    const tex = new THREE.Texture();
    const img = new Image();
    img.onload = () => {
      tex.image = img; tex.needsUpdate = true; barksSettled.add(name);
      // The trees drawn meanwhile in the plain colour take their bark now (see generateSpeciesTree).
      for (const m of barkMaterials.get(name) || []) { m.map = tex; m.color.copy(barkColour(SPECIES[name])); m.needsUpdate = true; }
      onBarkLoaded();
    };
    img.onerror = () => {
      console.warn(`[ez-trees] bark missing: ${BARK_DIR}${barkFile(name)}`);
      for (const m of barkMaterials.get(name) || []) { m.map = null; plainBark(m, SPECIES[name]); }
      barksSettled.add(name);
      onBarkLoaded();
    };
    img.src = BARK_DIR + barkFile(name);
    barks.set(name, tex);
  }
  return barks.get(name);
}

/**
 * Is a species' bark settled (arrived, or missing for good)? For the Panels' render signature (scene3d.js): a Panel drawn
 * before its trees' bark arrived must be drawn again when it does. Seen on 16 Nov. 2026: a Case drawn first kept,
 * from its cache, oaks with plain WHITE branches (a texture without its image: transparent, the white page showing
 * through), the redraw on arrival serving the same image. True where there is no DOM (tests: no bark is ever asked).
 */
export function barkSettled(name) {
  return typeof document === 'undefined' || typeof Image === 'undefined' || barksSettled.has(name);
}

/** A bark's plain colour (its texture missing): a grey-brown, tinted by the species. */
function plainBark(material, sp) {
  material.color.set(BARK_FALLBACK).multiply(barkColour(sp));
  material.needsUpdate = true;
}

/** A species' bark colour: its tint, times its gain (above white for a bark lightened). */
export function barkColour(sp) {
  return new THREE.Color(sp.barkTint).multiplyScalar(sp.barkGain || 1);
}

/**
 * How many times the bark goes round the TRUNK. EZ-Tree 2 puts the turns in the u coordinate itself: round(radius ×
 * `bark.textureScale.x`) for each branch, at least 1 (its bark as large on a twig as on the trunk); `speciesOptions`
 * sets that scale so the trunk gets these turns.
 */
const BARK_AROUND = 2;

/**
 * The bark's repeat, its texels square on the trunk: u already goes BARK_AROUND times round it (EZ-Tree 2), v from 0
 * to 1 up one section; the trunk is 2π·r round and a section length/sections high. A fixed repeat squeezed the bark
 * 17 times on the plane's trunk (21 units round, 3.75 a section): mipmaps then averaged it to a plain brown (seen).
 */
export function barkRepeat(options) {
  const round = 2 * Math.PI * options.branch.radius[0];
  const section = options.branch.length[0] / options.branch.sections[0];
  return [1, BARK_AROUND * section / round];
}

/**
 * The levels of detail of our trees (EZ-Tree 2's `generateLODs`), their distances in METRES from the camera (a
 * tree is set to its height in metres: the levels switch on the world's distance): EZ-Tree's own details (about 40 %
 * of the triangles, then 20 %), nearer than its units because our trees are 7 to 30 m, its own 40 to 70 units.
 */
export const SPECIES_LODS = [
  { distance: 0, detail: {} },
  { distance: 60, detail: { sectionStride: 3, segmentFactor: 0.75, leafStride: 2, leafScale: 1.25 } },
  { distance: 150, detail: { sectionStride: 6, segmentFactor: 0.4, leafStride: 2, leafScale: 1.3, billboard: 'single' } },
];

/** The seed EZ-Tree gets for our variant `n` (1, 2…): spread apart, as in the trial (tools/ez-tree). */
export const SEED_STEP = 7919;

/** A bark when its texture is missing: a grey-brown, tinted by the species. */
const BARK_FALLBACK = 0x7a6a58;

/** The options of a species' variant: its preset, then its changes, then the seed. */
export function speciesOptions(name, variant = 1) {
  const sp = SPECIES[name];
  if (!sp) throw new Error(`Unknown tree species: ${name}`);
  const options = new TreeOptions();
  options.copy(JSON.parse(JSON.stringify(TREE_PRESETS[sp.from])));
  sp.set(options);
  // EZ-Tree 2: the bark's turns round a branch are round(radius × this); the trunk's, BARK_AROUND.
  options.bark.textureScale.x = BARK_AROUND / options.branch.radius[0];
  options.seed = variant * SEED_STEP;
  options.leaves.tint = 0xffffff;
  return options;
}

/**
 * A species' options made LIGHT, for trees copied by the hundred (an orchard, orchard-3d.js): about half the sections
 * round a branch and along it, half the leaves, larger, on one plane each. The same silhouette (the same seed and
 * branching), far fewer triangles.
 */
export function lightenOptions(options) {
  const b = options.branch;
  // Its finest twigs dropped (one level less, from three), their leaves borne by the level above, larger.
  if (b.levels >= 3) { b.levels -= 1; options.leaves.count = Math.round(options.leaves.count * 2.2); }
  for (const k of Object.keys(b.sections)) b.sections[k] = Math.max(3, Math.round(b.sections[k] * 0.4));
  for (const k of Object.keys(b.segments)) b.segments[k] = Math.max(3, Math.round(b.segments[k] * 0.5));
  options.leaves.count = Math.max(3, Math.round(options.leaves.count * 0.55));
  options.leaves.size *= 1.9;
  options.leaves.billboard = 'single';
  return options;
}

/**
 * Generates a species' variant, at EZ-Tree's own scale. `makeCanvas(size)` draws the foliage (a DOM canvas by
 * default); `barkTexture(name)` gives the species' bark texture, or null (a plain colour then): the shipped file
 * by default.
 */
export function generateSpeciesTree(name, variant = 1, { makeCanvas = domCanvas, barkTexture = shippedBark, lods = SPECIES_LODS, light = false } = {}) {
  const sp = SPECIES[name];
  const options = speciesOptions(name, variant);
  if (light) lightenOptions(options);
  const tree = new Tree(options);
  // Its levels of detail (EZ-Tree 2): all on one skeleton and sharing the two materials set below; `lods: null`,
  // the full tree only.
  if (lods) tree.generateLODs(lods);
  else tree.generate();

  const leaf = new THREE.CanvasTexture(sp.foliage(variant, makeCanvas));
  const leaves = tree.leavesMesh.material;
  leaves.map = leaf;
  leaves.color.set(0xffffff);
  opaqueCutout(leaves);

  const bark = barkTexture(name);
  const branches = tree.branchesMesh.material;
  if (bark) {
    bark.wrapS = bark.wrapT = THREE.RepeatWrapping;
    bark.repeat.set(...barkRepeat(tree.options));
    // Seen at a slant on a trunk, a bark blurs without it (three keeps it within what the GPU allows).
    bark.anisotropy = 8;
    // Its image not there yet (the first trees after a launch): the plain colour until it arrives, never the empty
    // texture (seen on 17 Nov. 2026: WHITE branches on the first preview, the image without its picture transparent,
    // the page through it); shippedBark's onload gives the map to every material waiting.
    if (bark.image) { branches.map = bark; branches.color.copy(barkColour(sp)); }
    else plainBark(branches, sp);
    if (!barkMaterials.has(name)) barkMaterials.set(name, []);
    barkMaterials.get(name).push(branches);
  } else {
    plainBark(branches, sp);
  }
  leaves.needsUpdate = branches.needsUpdate = true;
  tree.userData.species = name;
  tree.userData.variant = variant;
  return tree;
}


/** The generated variants, for the session (a few: our species times their variants). */
const cache = new Map();

/** A variant generated once: the tree, its height and its foot (EZ-Tree's units), its crown (plan, unit height). */
function variantOf(name, variant, options) {
  const key = `${name}|${variant}`;
  let model = cache.get(key);
  if (!model) {
    const tree = generateSpeciesTree(name, variant, options);
    const box = new THREE.Box3().setFromObject(tree);
    model = { tree, box, height: box.max.y - box.min.y, foot: box.min.y };
    cache.set(key, model);
  }
  return model;
}

/** The convex hull of points { x, z } (monotone chain), counter-clockwise. */
function hullOf(points) {
  const p = [...points].sort((a, b) => a.x - b.x || a.z - b.z);
  if (p.length < 3) return p;
  const cross = (o, a, b) => (a.x - o.x) * (b.z - o.z) - (a.z - o.z) * (b.x - o.x);
  const lower = [], upper = [];
  for (const q of p) { while (lower.length >= 2 && cross(lower[lower.length - 2], lower[lower.length - 1], q) <= 0) lower.pop(); lower.push(q); }
  for (const q of p.reverse()) { while (upper.length >= 2 && cross(upper[upper.length - 2], upper[upper.length - 1], q) <= 0) upper.pop(); upper.push(q); }
  return lower.slice(0, -1).concat(upper.slice(0, -1));
}

/**
 * The CROWN of a species' variant, seen from above, for a tree 1 high: its outline (convex hull of its leaves,
 * around the trunk at (0, 0), unrotated) and the height its crown starts at (0 to 1). What the import needs to
 * keep a crown out of the buildings (placement-clearance.js), its trunk where the tree stands.
 */
export function crownOf(name, variant = 1, options = {}) {
  const m = variantOf(name, variant, options);
  if (!m.crown) {
    const pos = m.tree.leavesMesh.geometry.attributes.position;
    const pts = [], ys = [];
    for (let i = 0; i < pos.count; i++) {
      pts.push({ x: pos.getX(i) / m.height, z: pos.getZ(i) / m.height });
      ys.push(pos.getY(i));
    }
    // Where the crown starts: its lowest 5 % of leaves aside (a stray drooping leaf is not the crown: the olive's
    // lowest came at 1 % of its height).
    ys.sort((a, b) => a - b);
    const low = ys[Math.floor(ys.length * 0.05)];
    m.crown = { hull: hullOf(pts), base: Math.max(0, (low - m.foot) / m.height) };
  }
  return m.crown;
}

/**
 * A tree of `heightM` metres, its foot at (0, 0, 0): a clone of the variant generated once. Same options as
 * generateSpeciesTree. Its trunk at the centre of its box: the render centres a rig's box on its Element
 * (scene3d.js), and a crown leaning one way would move the trunk off the tree's place; an invisible box,
 * as wide each side of the trunk, is counted by the box and seen by nothing.
 */
export function speciesTree(name, variant, heightM, options = {}) {
  const model = variantOf(name, variant, options);
  const k = heightM / model.height;
  const group = new THREE.Group();
  // Its meshes cloned into a plain group: Tree.clone() would build a Tree, two empty meshes more.
  const copy = new THREE.Group();
  for (const m of model.tree.children) copy.add(m.clone());
  copy.position.y = -model.foot;
  group.add(copy);
  const hx = Math.max(-model.box.min.x, model.box.max.x), hz = Math.max(-model.box.min.z, model.box.max.z);
  const frame = new THREE.Mesh(new THREE.BoxGeometry(2 * hx, model.height, 2 * hz));
  frame.position.y = model.height / 2;
  frame.visible = false;
  frame.layers.set(31);
  frame.userData.gabarit = true;
  group.add(frame);
  group.scale.setScalar(k);
  group.userData = { species: name, variant, heightM };
  return group;
}
